    /// True if `itemId` can never be listed on the AH, so a bid on it can never fill.
    public static bool Contains(ushort itemId)
    {
        int lo = 0, hi = Ranges.Length - 1;
        while (lo <= hi)
        {
            int mid = (lo + hi) / 2;
            if (itemId < Ranges[mid].lo) hi = mid - 1;
            else if (itemId > Ranges[mid].hi) lo = mid + 1;
            else return true;
        }
        return false;
    }
}
